import{_ as a,o as e,c as r,a2 as d}from"./chunks/framework.doxMM-x8.js";const b=JSON.parse('{"title":"Lab Word 项目文档","description":"","frontmatter":{"docLocale":"zh","counterpart":"/en/docs/","contentType":"overview","prev":false,"next":{"text":"快速开始","link":"/getting-started/quickstart"}},"headers":[],"relativePath":"docs/index.md","filePath":"docs/index.md"}'),o={name:"docs/index.md"};function n(i,t,c,s,h,l){return e(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="lab-word-项目文档" tabindex="-1">Lab Word 项目文档 <a class="header-anchor" href="#lab-word-项目文档" aria-label="Permalink to &quot;Lab Word 项目文档&quot;">​</a></h1><p>Lab Word 面向实验室数字孪生。应用持久保存资产、Lab、对象和布局。后端程序提供来源明确的设备观测和 Task。</p><h2 id="选择你的任务" tabindex="-1">选择你的任务 <a class="header-anchor" href="#选择你的任务" aria-label="Permalink to &quot;选择你的任务&quot;">​</a></h2><table tabindex="0"><thead><tr><th>任务</th><th>从哪里开始</th><th>可观察结果</th></tr></thead><tbody><tr><td>启动现有应用</td><td><a href="./../getting-started/quickstart">快速开始</a></td><td>API 就绪、Web 注册页可访问</td></tr><tr><td>查看设备模型</td><td><a href="./../guides/lab-viewer">Lab 与资产库</a></td><td>查看模型并发布持久 GLB 资产</td></tr><tr><td>管理设备生命周期</td><td><a href="./../tutorials/entity-lifecycle">对象生命周期</a></td><td>替换外观并归档已停止 Entity</td></tr><tr><td>完成 Foundation 路径</td><td><a href="./../tutorials/complete-foundation">完整旅程</a></td><td>操作同一共享 Lab 并复现参考负载</td></tr><tr><td>修改项目</td><td><a href="./../architecture/project-structure">项目结构</a></td><td>找到应用组装与业务所有权</td></tr><tr><td>查阅接口</td><td><a href="./../reference/api">API</a>与<a href="./../reference/config">配置</a></td><td>定位当前生成合同与默认值</td></tr></tbody></table><h2 id="当前能力与计划" tabindex="-1">当前能力与计划 <a class="header-anchor" href="#当前能力与计划" aria-label="Permalink to &quot;当前能力与计划&quot;">​</a></h2><p>应用通过<a href="./../guides/platform">平台能力</a>提供身份、成员、知识库、文件与任务。Lab 是登录后的默认入口。已接受的 Viewer 和 Foundation 预览提供体验基准。</p><p>从<a href="./../tutorials/persistent-assets">持久资产</a>开始跟做双语教程，依次建立身份、布局、程序、同步、Task、历史和生命周期。<a href="./../tutorials/complete-foundation">完整旅程</a>全程使用同一当前工作副本和同一个 Lab。它提供独立、可丢弃的 100 Entity、20 台设备、双浏览器参考负载。真实设备接入仍属后续范围。<a href="./../architecture/lab-word">产品范围</a>说明这些边界。</p><h2 id="阅读与维护" tabindex="-1">阅读与维护 <a class="header-anchor" href="#阅读与维护" aria-label="Permalink to &quot;阅读与维护&quot;">​</a></h2><p>教程逐步增加同一份 Lab 业务代码；独立指南以任务、前提、源码、命令、结果和失败边界组织。当前内容只声明仓库实际存在的能力，预览与计划分别标明状态。</p><p>中英文页面按章节配对，API 与配置从实现生成。修改功能时同步更新相关文档和<a href="./../testing/feedback-loop">验证入口</a>，写作规则见<a href="./../guides/documentation">维护项目文档</a>。</p><hr><p>源码版本：<code>2fef28c35afe</code> · <a href="https://github.com/CaiZongyuan/labworld/blob/2fef28c35afea44ae2018f0e4b6a3a18a96a2bf7/docs/getting-started/documentation.md" target="_blank" rel="noreferrer">本页 Markdown</a></p>',12)])])}const u=a(o,[["render",n]]);export{b as __pageData,u as default};
